// Build-time capability inventory for deploy-aware discovery (#601).
//
// Every route in the build is mounted (no server-side feature flags), so
// "what is deployed" == "what build is deployed". This script inventories
// the route table and emits a family → boolean map consumed by
// deploy/agent-discovery.mjs's agentCard(). The checked-in
// deploy/capabilities.mjs is regenerated by the wrangler build.command
// next to stamp-version.mjs; `node scripts/build-capabilities.mjs --check`
// fails when the checked-in copy drifts from the route sources.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { join, dirname } from "node:path";
import { routeCandidates } from "./open-routes.mjs";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = join(root, "deploy", "capabilities.mjs");

// Capability families as [name, predicate] over a route template path.
// A family is true when at least one route in the build matches. Families
// are independent booleans; removing a family's routes from the server
// flips its flag to false in the next build's card.
export const FAMILIES = [
  ["agent-identities", p => /^\/api\/(agent-identities|identity-create)(\/|$)/.test(p)],
  ["agent-invites", p => /agent-invites/.test(p) || /^\/api\/invitations(\/|$)/.test(p)],
  ["agent-keys", p => /^\/api\/agent-keys(\/|$)/.test(p)],
  ["agent-rooms", p => /^\/api\/agent-rooms(\/|$)/.test(p)],
  ["guest-agent-links", p => /guest-agent-links/.test(p)],
  ["directory", p => /\/directory(\/|$)/.test(p) || /\/agent-directory(\/|$)/.test(p)],
  ["agent-inbox", p => /^\/api\/inbox(\/|$)/.test(p) || /\/agent-inbox(\/|$)/.test(p)],
  ["collab", p => /\/collab\//.test(p)],
  ["webhooks", p => /webhook/.test(p)],
  // Wakeable host registration (POST /api/agent-heartbeats). The A2A
  // pushNotifications flag is derived from this family plus webhooks;
  // see pushNotificationsSupported in deploy/agent-discovery.mjs.
  ["agent-heartbeats", p => /^\/api\/agent-heartbeats(\/|$)/.test(p)],
  ["public-face", p => /public-face/.test(p) || /^\/api\/public\//.test(p)],
  ["spend-allowance", p => /spend-allowance/.test(p)],
  ["web-fetch", p => /^\/api\/web\/fetch(\/|$)/.test(p)],
];

// Route templates served by server/agent-plugin-routes.mjs (mounted by
// server/http.mjs via createAgentPluginRoutes). routeCandidates() cannot
// expand that module's anchored regexes, so extract them directly:
//  - `path: "/api/…"` string literals in the route descriptors, and
//  - anchored `/^\/api\/…/` regex constants, truncated at the first regex
//    metacharacter after the literal prefix.
export function pluginRoutes(source) {
  const routes = new Set();
  for (const m of source.matchAll(/path:\s*[`'"](\/api\/[^`'"]+)[`'"]/g)) {
    routes.add(m[1].replace(/\$\{[^}]+\}/g, "{id}"));
  }
  for (const m of source.matchAll(/=\s*\/\^((?:\\\/|[A-Za-z0-9_{}$.-])+)/g)) {
    const prefix = m[1].replaceAll("\\/", "/");
    if (prefix.startsWith("/api/")) routes.add(prefix.replace(/\/{2,}/g, "/"));
  }
  return [...routes].sort();
}

export function buildCapabilities(paths) {
  const out = {};
  for (const [name, test] of FAMILIES) out[name] = paths.some(test);
  return out;
}

export function renderCapabilitiesModule(map) {
  const entries = Object.entries(map).map(([k, v]) => `  ${JSON.stringify(k)}: ${v},`).join("\n");
  return `// Generated by scripts/build-capabilities.mjs — do not hand-edit.\n// Regenerate: node scripts/build-capabilities.mjs\n// Capability families inventory the route table at build time (#601).\nexport const CAPABILITIES = Object.freeze({\n${entries}\n});\n`;
}

export function inventoryRoutes() {
  const httpSrc = readFileSync(join(root, "server", "http.mjs"), "utf8");
  const pluginSrc = readFileSync(join(root, "server", "agent-plugin-routes.mjs"), "utf8");
  return [...new Set([...routeCandidates(httpSrc), ...pluginRoutes(pluginSrc)])].sort();
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const map = buildCapabilities(inventoryRoutes());
  if (process.argv.includes("--json")) {
    console.log(JSON.stringify(map, null, 2));
  } else if (process.argv.includes("--check")) {
    const current = readFileSync(OUT, "utf8");
    if (current !== renderCapabilitiesModule(map)) {
      console.error("deploy/capabilities.mjs is stale — run: node scripts/build-capabilities.mjs");
      process.exit(1);
    }
    console.log(`capabilities current: ${Object.keys(map).length} families, ${Object.values(map).filter(Boolean).length} live`);
  } else {
    writeFileSync(OUT, renderCapabilitiesModule(map));
    console.log(`wrote ${OUT}: ${Object.keys(map).length} families, ${Object.values(map).filter(Boolean).length} live`);
  }
}
